import { test, expect } from '@playwright/test';

test.describe('Search Filter - Exclude Term with Minus Prefix', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/search');
    await page.waitForLoadState('networkidle');
  });

  test('should exclude results containing the term prefixed with minus sign', async ({ page }) => {
    const searchInput = page.getByRole('searchbox');
    await searchInput.fill('javascript -tutorial');

    const searchButton = page.getByRole('button', { name: /search/i });
    await searchButton.click();

    await page.waitForLoadState('networkidle');

    const results = page.getByRole('list').locator('li');
    const resultCount = await results.count();

    expect(resultCount).toBeGreaterThan(0);

    for (let i = 0; i < resultCount; i++) {
      const resultText = await results.nth(i).textContent();
      expect(resultText?.toLowerCase()).not.toContain('tutorial');
    }
  });

  test('should display correct results when excluding multiple terms', async ({ page }) => {
    const searchInput = page.getByRole('searchbox');
    await searchInput.fill('python -django -flask');

    const searchButton = page.getByRole('button', { name: /search/i });
    await searchButton.click();

    await page.waitForLoadState('networkidle');

    const results = page.getByRole('list').locator('li');
    const resultCount = await results.count();

    expect(resultCount).toBeGreaterThan(0);

    for (let i = 0; i < resultCount; i++) {
      const resultText = await results.nth(i).textContent();
      const lowerText = resultText?.toLowerCase() || '';
      expect(lowerText).not.toContain('django');
      expect(lowerText).not.toContain('flask');
    }
  });

  test('should include positive search term while excluding negative term', async ({ page }) => {
    const searchInput = page.getByRole('searchbox');
    await searchInput.fill('react -native');

    const searchButton = page.getByRole('button', { name: /search/i });
    await searchButton.click();

    await page.waitForLoadState('networkidle');

    const results = page.getByRole('list').locator('li');
    const resultCount = await results.count();

    expect(resultCount).toBeGreaterThan(0);

    let hasReactResults = false;
    for (let i = 0; i < resultCount; i++) {
      const resultText = await results.nth(i).textContent();
      const lowerText = resultText?.toLowerCase() || '';

      if (lowerText.includes('react')) {
        hasReactResults = true;
      }
      expect(lowerText).not.toContain('native');
    }

    expect(hasReactResults).toBe(true);
  });

  test('should handle minus prefix at different positions in search query', async ({ page }) => {
    const searchInput = page.getByRole('searchbox');
    await searchInput.fill('-spam email marketing');

    const searchButton = page.getByRole('button', { name: /search/i });
    await searchButton.click();

    await page.waitForLoadState('networkidle');

    const results = page.getByRole('list').locator('li');
    const resultCount = await results.count();

    expect(resultCount).toBeGreaterThan(0);

    for (let i = 0; i < resultCount; i++) {
      const resultText = await results.nth(i).textContent();
      expect(resultText?.toLowerCase()).not.toContain('spam');
    }
  });

  test('should display message when all results are excluded', async ({ page }) => {
    const searchInput = page.getByRole('searchbox');
    await searchInput.fill('test -test');

    const searchButton = page.getByRole('button', { name: /search/i });
    await searchButton.click();

    await page.waitForLoadState('networkidle');

    const noResultsMessage = page.getByText(/no results found|no matches/i);
    const results = page.getByRole('list').locator('li');
    const resultCount = await results.count();

    if (resultCount === 0) {
      await expect(noResultsMessage).toBeVisible();
    }
  });
});
